select d.dept_name, case when d.budget >= 4096000 then 'high' when d.budget >= 2046000 then 'mid' else 'low' end as budget_bucket, max(e.salary) - min(e.salary) as salary_range, concat_ws(', ', sort_array(collect_set(e.level))) as level_values from employees e join departments d on e.dept_id = d.id group by d.dept_name, case when d.budget >= 4096000 then 'high' when d.budget >= 2046000 then 'mid' else 'low' end order by level_values, 2
